<x-filament::page>
@php
    $app = $this->activeApp;
    $stats = $this->stats ?? [];
    $recentComments = collect($this->recentComments ?? []);
    $tabs = ['overview'=>'Overview','pending'=>'Pending','published'=>'Published','hidden'=>'Hidden','recent'=>'Recent Comments','guide'=>'Safety Guide'];
    $activeTab = strtolower((string) request('tab','overview'));
    if (! array_key_exists($activeTab, $tabs)) $activeTab = 'overview';
    $formatDate = function ($value) {
        if (! $value) return '—';
        try { return \Carbon\Carbon::parse($value)->timezone(config('app.timezone','Africa/Lagos'))->format('M j, Y · g:i A'); }
        catch (\Throwable $e) { return (string) $value; }
    };
    $commentsForTab = match ($activeTab) {
        'pending' => $recentComments->where('status', \App\Models\ContentPostComment::STATUS_PENDING)->values(),
        'published' => $recentComments->where('status', \App\Models\ContentPostComment::STATUS_PUBLISHED)->values(),
        'hidden' => $recentComments->where('status', \App\Models\ContentPostComment::STATUS_HIDDEN)->values(),
        default => $recentComments->take(20)->values(),
    };
@endphp

